exercises.solution:
class Node:
    def __init__(self,v):
        self.value=v; self.left=None; self.right=None
root=Node(1); root.left=Node(2); root.right=Node(3)
def total(n):
    if n is None: return 0
    return n.value+total(n.left)+total(n.right)
print(total(root))

